void CSecretWhisperingMan::OnPredicateFail()
{
    if (Me.MsgIsKilledBy("")) {
        ParentClass->ParanoidState = 5;
        ParentClass->HideDiggingSpot = false;
        Game->SetQuestCardObjective("V_MayorsInvitation", "TEXT_QUEST_MAYORS_INVITATION_OBJECTIVE_05", "OakBay", "");
